   "resume": "Le samedi 9 juillet 2022, la parade « Rave the Planet », portée par Dr. Motte (cofondateur de la Love Parade, avec Danielle de Picciotto), part du Kurfürstendamm vers la Colonne de la Victoire (Grosser Stern) et dure jusqu'à 21 h 20 environ, quand la police l'arrête après le dernier meeting. Les organisateurs annoncent environ 300 000 participants ; la police et la presse berlinoise (rbb24, Tagesspiegel, d'après Resident Advisor) en comptent environ 200 000.",
