   "lieu": "Allemagne (Berlin)",
   "resume": "Le 13 mars 2024, la Conférence des ministres de la Culture des Länder et la déléguée du gouvernement fédéral à la Culture et aux Médias ajoutent la « Berliner Technokultur » au registre allemand du patrimoine culturel immatériel (Bundesweites Verzeichnis). Il s'agit d'une liste nationale, pas de la liste du patrimoine immatériel de l'UNESCO au niveau mondial, même si plusieurs médias titrent « UNESCO ». L'association Rave the Planet, avec Dr. Motte, a porté la candidature.",
